'use strict';

// MODULES //

var resolve = require( 'path' ).resolve;
var tape = require( 'tape' );
var tryRequire = require( '@stdlib/utils/try-require' );
var run = require( './helpers.js' );
var factory = require( './../lib/factory.js' );
var eligible = require( './../lib/can_use_native.js' );
var main = require( './../lib/main.js' );


// VARIABLES //

var addon = tryRequire(resolve(__dirname, '../src/addon.node'));
var opts = {
	'skip': (addon instanceof Error)
};


// TESTS //

tape( 'main export is a function', opts, function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof addon, 'function' );
	t.end();
});

tape('dgbtf2: actual compiled native reference and reconstruction', opts, function test(t) {
	var native;
	var calls = 0;
	native = factory(function backend() {
		calls += 1;
		return addon.apply(null, arguments);
	}, eligible, main);
	run(t, native);
	t.ok((calls > 200), 'actual loaded addon dispatched for positive fixtures');
	t.end();
});
tape('dgbtf2: raw quartet signed32 before empty', opts, function test(t) {
	t.throws(function bad() {
		addon(2147483648, 0, 0, 0, null, 1, 1, 0, null, 1, 0);
	}, Error, 'rejects oversized raw M before quick return');
	t.strictEqual(addon(0, 0, 0, 0, null, null, null, null, null, null, null), 0, 'valid raw empty avoids inactive metadata');
	t.end();
});
